import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'src'))

from docich.hanjuku_speedrun.hanjuku import orchestrator as O
from docich.hanjuku_speedrun.hanjuku.strategy import replan


@pytest.fixture()
def armed(monkeypatch):
    calls = []
    monkeypatch.setattr(replan, '_off_chart', lambda mem: calls.append(mem))
    return calls


def memory(**extra):
    mem = {'chapter': 11, 'tick': 100000, 'chart_plan_tick': 45221,
           'world': {'sorties': {}}, 'plan': {'chart_plan': {'orders': []}},
           '_records': []}
    mem.update(extra)
    return mem


def test_a_stale_plan_is_rebuilt_during_a_battle(armed):
    mem = memory()
    assert O.plan_starved_rearm(mem, 'battle', 'battle') is True
    assert armed and mem['chart_plan_tick'] == 100000
    assert any(r['decision'] == 'plan_starved_rearm' for r in mem['_records'])


def test_a_map_frame_is_left_to_the_normal_flow(armed):
    assert O.plan_starved_rearm(memory(), 'field', 'map') is False
    assert not armed


def test_a_fresh_plan_is_not_rebuilt(armed):
    mem = memory(chart_plan_tick=99900)
    assert O.plan_starved_rearm(mem, 'battle', 'battle') is False
    assert not armed


def test_a_march_in_flight_is_not_disturbed(armed):
    mem = memory(world={'sorties': {'S1': {'status': 'en_route'}}})
    assert O.plan_starved_rearm(mem, 'battle', 'battle') is False
    assert not armed


def test_a_settled_record_does_not_block_the_rearm(armed):
    mem = memory(world={'sorties': {'S1': {'status': 'overdue'}}})
    assert O.plan_starved_rearm(mem, 'battle', 'battle') is True
    assert armed
